/* Digital Factory Lab – Robot bookings (Moodle Database JavaScript template).
   List page: groups bookings by day, filters, flags conflicts. Add/Edit page: checks the time
   against other bookings (and the availability board) before saving. */
(function () {
  /* ======== settings ======== */
  var AVAIL_DB = 0;        // id of the "Robot availability" database (the number after d= in its URL); 0 = don't check
  var OPEN = 8, CLOSE = 18, MAX_HOURS = 10;
  var DAYS = [1, 2, 3, 4, 5];  // bookable weekdays, 1 = Monday
  // Robots that are ALSO a station: robot name -> d= number of that station's booking database (0 = not linked).
  // A booking on either side blocks the same time on the other side.
  var STATION_DBS = { "Taurob - Sieglinde": 2333, "MiR with UR5": 2332, "ABB CRB 15000-5/0.95 (GoFa)": 2335, "Wittmann W818-2058": 2337 };            // add the robot, with the station's d=
  var STATION_NAMES = { "Wittmann W818-2058": "3D Printing Farm" };   // robot name → station name

  var ACCESS_DB = 2338;       // d= of "Station access": linked robots can then only be booked by people on that station's list; 0 = anyone
  var ALL_ROBOTS_NEED_ACCESS = true;   // true = every robot needs an entry in "Station access" (robot name as station); false = only robots linked to a station
  var ONLY_MY_ROBOTS = true;           // true = show only the robots you may book (the Leader sees all)
  var ROBOTS = {"WAVEGO EX Bionic Dog": {"cell": "FLOOR", "maker": "Waveshare", "art": "wavego_bionic"}, "Galaxy RVR Mars Rover": {"cell": "FLOOR", "maker": "SunFounder", "art": "galaxy_rvr_rover"}, "RaspRover (tracked, with arm)": {"cell": "FLOOR", "maker": "Waveshare", "art": "rasprover_tracked"}, "Double-Deck Robot Chassis": {"cell": "BENCH", "maker": "BerryBase", "art": "berrybase_chassis"}, "LiDAR Bot AGV with Mecanum Wheels": {"cell": "FLOOR", "maker": "M5Stack", "art": "mecanum"}, "SO-ARM101": {"cell": "TABLE", "maker": "TheRobotStudio / Hugging Face (open source)", "art": "so_arm"}, "Mini Wheeled-Legged Robot": {"cell": "FLOOR", "maker": "StackForce", "art": "stackforce_wheeled"}, "Dancing Robot": {"cell": "SHELF", "maker": "Playtastic", "art": "playtastic_humanoid"}, "TurtleBot3 Burger": {"cell": "FLOOR", "maker": "ROBOTIS", "art": "turtlebot3"}, "Robotis Dynamixel Hexapod MKII": {"cell": "FLOOR", "maker": "Interbotix / ROBOTIS", "art": "hexapod"}, "Taurob - Sieglinde": {"cell": "FLOOR", "maker": "taurob", "art": "taurob"}, "Zelos": {"cell": "FLOOR", "maker": "Not specified", "art": "zelos"}, "MiR with UR5": {"cell": "FLOOR", "maker": "Mobile Industrial Robots (MiR)", "art": "mir_ur5"}, "Unitree G1 EDU U2 Advanced": {"cell": "FLOOR", "maker": "Unitree Robotics", "art": "humanoid"}, "Festo Robotino 3": {"cell": "FLOOR", "maker": "Festo", "art": "robotino"}, "KUKA KR 16-2": {"cell": "CELL", "maker": "KUKA", "art": "kuka_kr16"}, "Wittmann W818-2058": {"cell": "CELL", "maker": "WITTMANN", "art": "wittmann"}, "UR5": {"cell": "CELL", "maker": "Universal Robots", "art": "ur5"}, "ABB CRB 15000-5/0.95 (GoFa)": {"cell": "CELL", "maker": "ABB", "art": "abb_gofa"}, "KUKA KR 6 R900 sixx": {"cell": "CELL", "maker": "KUKA", "art": "kuka_kr6"}, "FANUC M-6iB": {"cell": "CELL", "maker": "FANUC", "art": "fanuc_m6ib"}, "FANUC ER-4iA": {"cell": "CELL", "maker": "FANUC", "art": "fanuc_er4ia"}};     // robot name -> {cell, maker, art}
  var IMG = pictures();            // robot pictures – at the very end of this file
  /* ========================== */

  var MONTHS = { january: 1, jan: 1, januar: 1, "jänner": 1, february: 2, feb: 2, februar: 2, "feber": 2, march: 3, mar: 3, "märz": 3, "mär": 3,
    april: 4, apr: 4, may: 5, mai: 5, june: 6, jun: 6, juni: 6, july: 7, jul: 7, juli: 7, august: 8, aug: 8, september: 9, sep: 9, sept: 9,
    october: 10, oct: 10, oktober: 10, okt: 10, november: 11, nov: 11, december: 12, dec: 12, dezember: 12, dez: 12 };
  var WD = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
  function txt(el) { return el ? el.textContent.replace(/\s+/g, " ").trim() : ""; }
  function pad(n) { return (n < 10 ? "0" : "") + n; }
  function iso(y, m, d) { return y + "-" + pad(m) + "-" + pad(d); }
  function today() { var d = new Date(); return iso(d.getFullYear(), d.getMonth() + 1, d.getDate()); }
  function dow(s) { var p = s.split("-"); return (new Date(+p[0], +p[1] - 1, +p[2]).getDay() + 6) % 7 + 1; }
  function nice(s) { var p = s.split("-"); return WD[dow(s) - 1] + ", " + p[2] + "." + p[1] + "." + p[0]; }
  function hh(h) { return pad(h) + ":00"; }
  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }
  /* Moodle shows the date like "18 November 2026" (English) or "18. November 2026" (German) */
  function parseShown(s) {
    var m = s.toLowerCase().match(/(\d{1,2})\.?\s*([a-zäö]+)\.?,?\s*(\d{4})/);
    if (m && MONTHS[m[2]]) { return iso(+m[3], MONTHS[m[2]], +m[1]); }
    m = s.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/); if (m) { return iso(+m[3], +m[2], +m[1]); }
    m = s.match(/(\d{4})-(\d{2})-(\d{2})/); if (m) { return m[0]; }
    return "";
  }
  function hour(s) { var m = String(s).match(/(\d{1,2})/); return m ? +m[1] : NaN; }
  function param(n) { var m = location.search.match(new RegExp("[?&]" + n + "=([^&]*)")); return m ? decodeURIComponent(m[1].replace(/\+/g, " ")) : ""; }
  function selfQuery() { return param("d") ? "d=" + param("d") : "id=" + param("id"); }

  function readBookings(root) {
    var out = [];
    Array.prototype.forEach.call(root.querySelectorAll(".bk-e"), function (e) {
      out.push({ el: e, id: +e.getAttribute("data-id") || 0, robot: txt(e.querySelector(".bk-robot")),
        date: parseShown(txt(e.querySelector(".bk-date"))), from: hour(txt(e.querySelector(".bk-from"))),
        to: hour(txt(e.querySelector(".bk-to"))), user: txt(e.querySelector(".bk-user")), note: txt(e.querySelector(".bk-note")),
        uid: (function (a) { var m = a ? (a.getAttribute("href") || "").match(/[?&]id=(\d+)/) : null; return m ? +m[1] : 0; })(e.querySelector(".bk-user a")) });
    });
    return out;
  }
  function readBoard(root) {          // cards of the availability database
    var out = {};
    Array.prototype.forEach.call(root.querySelectorAll(".tdf-card"), function (c) {
      var u = txt(c.querySelector(".tdf-until")).match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);
      out[txt(c.querySelector(".tdf-name"))] = { status: c.getAttribute("data-st") || txt(c.querySelector(".tdf-status")),
        person: (c.getAttribute("data-person") || txt(c.querySelector(".tdf-person"))).replace(/^@\s*/, ""),
        until: u ? iso(+u[3], +u[2], +u[1]) : "" };
    });
    return out;
  }
  function fetchPage(query) {
    return fetch("view.php?" + query + "&perpage=1000", { credentials: "same-origin" })
      .then(function (r) { if (!r.ok) { throw new Error(r.status); } return r.text(); })
      .then(function (h) { return new DOMParser().parseFromString(h, "text/html"); });
  }
  /* ---------- Station access list (who may book which station) ----------
     Rules: the Leader (Moodle user ids in data-leaders on the "Station access" list header)
     adds Supervisors; a Supervisor adds Students for HIS stations only. Entries added by
     anyone else are ignored. Moodle saves who wrote each entry, so this can't be faked. */
  function acNorm(s) { return String(s || "").toLowerCase().replace(/\s+/g, " ").trim(); }
  /* "Simon Huber (id 123)" -> {name: "Simon Huber", id: 123}; a name without id still works */
  function acPerson(s) { var m = String(s || "").match(/^(.*?)\s*\(id\s*(\d+)\)\s*$/i); return m ? { name: m[1].trim(), id: +m[2] } : { name: String(s || "").trim(), id: 0 }; }
  function acGet(url) {
    return fetch(url, { credentials: "same-origin" })
      .then(function (r) { if (!r.ok) { throw new Error(r.status); } return r.text(); })
      .then(function (h) { return new DOMParser().parseFromString(h, "text/html"); });
  }
  function readAccess(doc) {
    var cfg = doc.querySelector(".ac-config");
    var leaders = cfg ? (cfg.getAttribute("data-leaders") || "").split(/[^0-9]+/).filter(Boolean).map(Number) : [];
    var rows = Array.prototype.map.call(doc.querySelectorAll(".ac-e"), function (e) {
      var ua = e.querySelector(".ac-by a"), m = ua ? (ua.getAttribute("href") || "").match(/[?&]id=(\d+)/) : null;
      var ed = e.querySelector('.ac-actions a[href*="edit.php"]'), de = e.querySelector('.ac-actions a[href*="delete="]');
      var pp = acPerson(txt(e.querySelector(".ac-person")));
      return { id: +e.getAttribute("data-id") || 0, station: txt(e.querySelector(".ac-station")), person: pp.name, pid: pp.id,
        role: /super/i.test(txt(e.querySelector(".ac-role"))) ? "Supervisor" : "Student", note: txt(e.querySelector(".ac-note")),
        by: txt(e.querySelector(".ac-by")), byId: m ? +m[1] : 0, edit: ed ? ed.getAttribute("href") : "", del: de ? de.getAttribute("href") : "" };
    });
    var sup = {}, stu = {};
    // a person is matched by Moodle id when the entry has one, otherwise by name
    function put(map, st, r) { (map[st] = map[st] || {})[r.pid ? "#" + r.pid : acNorm(r.person)] = true; }
    function has(map, st, u) { var m = map[st]; return !!(m && u && ((u.id && m["#" + u.id]) || (u.name && m[acNorm(u.name)]))); }
    rows.forEach(function (r) {
      if (r.role !== "Supervisor") { return; }
      r.ok = leaders.indexOf(r.byId) >= 0;
      if (r.ok) { put(sup, r.station, r); } else { r.why = "only the Leader can add supervisors"; }
    });
    rows.forEach(function (r) {
      if (r.role !== "Student") { return; }
      r.ok = leaders.indexOf(r.byId) >= 0 || has(sup, r.station, { id: r.byId, name: r.by });
      if (r.ok) { put(stu, r.station, r); } else { r.why = r.by + " is not a supervisor of " + r.station; }
    });
    return {
      leaders: leaders, rows: rows,
      viewAsOff: !!cfg && /^(off|no|false|0)$/i.test(cfg.getAttribute("data-viewas") || ""),   // data-viewas="off" switches the preview off
      isLeader: function (u) { return !!u && !!u.id && leaders.indexOf(u.id) >= 0; },
      isSupervisor: function (u, st) { return has(sup, st, u); },
      supervisors: function (st) { return rows.filter(function (r) { return r.ok && r.role === "Supervisor" && r.station === st; }).map(function (r) { return r.person; }); },
      may: function (u, st) { return !!u && ((!!u.id && leaders.indexOf(u.id) >= 0) || has(sup, st, u) || has(stu, st, u)); }
    };
  }
  /* the logged-in user: id from the page header, full name from your own profile page */
  function whoAmIFull() {
    var el = document.querySelector("#nav-notification-popover-container[data-userid], #nav-message-popover-container[data-userid], [data-region='popover-region-notifications'][data-userid], .popover-region[data-userid]");
    var id = el ? +el.getAttribute("data-userid") || 0 : 0, root = (window.M && M.cfg && M.cfg.wwwroot) || "";
    return acGet(root + "/user/profile.php" + (id ? "?id=" + id : "")).then(function (doc) {
      var h = doc.querySelector(".page-header-headings h1, .page-context-header h1, .page-header-headings h2, #page-header h1, h1");
      return { id: id, name: txt(h) };
    }).catch(function () { return { id: id, name: "" }; });
  }
  /* course participants (name + Moodle id) from the Participants page – for picking people in the form */
  function loadParticipants() {
    var cm = (document.body.className.match(/\bcourse-(\d+)\b/) || [])[1] || (window.M && M.cfg && M.cfg.courseId), root = (window.M && M.cfg && M.cfg.wwwroot) || "";
    if (!cm) { return Promise.reject(new Error("no course id")); }
    return acGet(root + "/user/index.php?id=" + cm + "&perpage=5000").then(function (doc) {
      var seen = {}, out = [];
      Array.prototype.forEach.call(doc.querySelectorAll('#participants a[href*="/user/view.php"], table.generaltable a[href*="/user/view.php"]'), function (a) {
        var m = (a.getAttribute("href") || "").match(/[?&]id=(\d+)/); if (!m || seen[m[1]]) { return; }
        var c = a.cloneNode(true); Array.prototype.forEach.call(c.querySelectorAll(".userinitials, img, .sr-only, .visually-hidden"), function (x) { x.remove(); });
        var name = txt(c); if (!name) { return; }
        seen[m[1]] = 1; out.push({ id: +m[1], name: name });
      });
      if (!out.length) { throw new Error("no participants visible"); }
      return out.sort(function (a, b) { return a.name.localeCompare(b.name); });
    });
  }
  function loadAccess(db) {
    return acGet("view.php?d=" + db + "&perpage=1000").then(function (doc) {
      if (!doc.querySelector(".ac-config")) { throw new Error("not the access list"); }
      return readAccess(doc);
    });
  }
  /* ---------- "View as" preview (Leaders only) ----------
     The Leader picks a person on the Station access page; every booking page then behaves as for
     that person. Only for looking: anything saved is still saved under the Leader's own name. */
  /* open the current page again as a normal visit (a reload would make Firefox ask to resend a form) */
  function acReopen() {
    var m = location.search.match(/[?&](d|id)=(\d+)/), hid = document.querySelector('form input[name="d"]');
    if (m) { location.href = location.pathname + location.search; }
    else if (hid && hid.value) { location.href = "view.php?d=" + hid.value; }      // page reached by saving a form: no d= in the address
    else { location.href = location.pathname; }
  }
  function getViewAs() { try { return JSON.parse(sessionStorage.getItem("st-viewas") || "null"); } catch (e) { return null; } }
  function setViewAs(u) { try { if (u) { sessionStorage.setItem("st-viewas", JSON.stringify(u)); } else { sessionStorage.removeItem("st-viewas"); } } catch (e) {} }
  function viewAs(acc, me) {
    var v = getViewAs();
    if (!v || !acc || !me || !acc.isLeader(me) || acc.viewAsOff) { return me; }       // only a real Leader can preview (unless switched off)
    var u = { id: v.id || 0, name: v.name || "", real: me, preview: true };
    previewBanner(u, acc);
    return u;
  }
  function previewBanner(u, acc) {
    if (document.getElementById("st-preview")) { return; }
    var what = acc && acc.isLeader(u) ? "Leader" : acc && acc.rows.some(function (r) { return r.ok && r.role === "Supervisor" && acc.isSupervisor(u, r.station); }) ? "supervisor" : "student";
    var d = document.createElement("div"); d.id = "st-preview"; d.className = "st-preview";
    d.innerHTML = "👁 <b>Preview</b> – you see this page as <b>" + String(u.name).replace(/[&<>"]/g, "") + "</b> (" + what + "). Anything you save is still saved as you. " +
      '<button type="button" class="btn btn-sm btn-secondary">Stop preview</button>';
    d.querySelector("button").onclick = function () { setViewAs(null); acReopen(); };
    var root = document.querySelector(".bk") || document.body.firstElementChild;
    if (root && root.parentNode) { root.parentNode.insertBefore(d, root); } else { document.body.insertBefore(d, document.body.firstChild); }
  }
  /* styles for the preview banner and the name pickers (added from here, so the CSS template needn't change) */
  (function () {
    if (document.getElementById("ac-style")) { return; }
    var st = document.createElement("style"); st.id = "ac-style";
    st.textContent = ".st-preview{background:#fff4d6;border:1px solid #b7860b;border-radius:8px;padding:8px 14px;margin:0 0 12px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}" +
      ".ac-pick{position:absolute;z-index:50;left:0;right:0;top:100%;background:#fff;border:1px solid #d9dee5;border-radius:6px;box-shadow:0 6px 18px rgba(0,0,0,.12);max-height:320px;overflow:auto}" +
      ".ac-pick[hidden]{display:none}.ac-pick button{display:block;width:100%;text-align:left;border:0;background:#fff;padding:7px 12px}" +
      ".ac-pick button:hover,.ac-pick button:first-child{background:#eef3fb}.ac-id{color:#5b6472}" +
      ".ac-viewas{border:1px dashed #b7860b;background:#fffaf0;border-radius:8px;padding:10px 14px;margin:-4px 0 12px}.ac-hint{color:#5b6472;font-size:.85rem}" +
      ".ac-vrow{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-top:8px}.ac-vwrap{position:relative;display:inline-block;width:300px;max-width:100%}.ac-vwrap input{width:100%}" +
      ".ac-vq-btn{border:1px solid #d9dee5;background:#fff;border-radius:999px;padding:2px 10px;font-size:.85rem}.ac-vq-btn:hover{background:#eef3fb}" +
      ".bk-manage{display:flex;justify-content:flex-end;margin:0 0 10px}.ac-group{margin:16px 0 0;font-size:1.05rem;color:#5b6472}.st-controls{display:block;text-align:right;font-size:.8rem;color:#5b6472;margin:0 0 4px}";
    (document.head || document.documentElement).appendChild(st);
  })();
  /* ---------- clean page ----------
     Hides Moodle's own database controls (List view / Actions bar, Entries per page, Search, Sort,
     Advanced search, Save settings, paging) so only our page is left – for everyone.
     Editors get a small "Show Moodle controls" link (adds &tidy=0 to the address). */
  function acTidy() {
    var editor = document.querySelector("a[href*='/mod/data/templates.php'], a[href*='/mod/data/field.php'], a[href*='/mod/data/preset.php']");
    if (/[?&]tidy=0/.test(location.search)) { return; }
    var stop = document.getElementById("region-main") || document.querySelector("[role='main']");
    var first = document.querySelector(".bk-top, .ac-config"), ends = document.querySelectorAll(".bk-copy, .bk-list, #st-overview, #ac-view"), last = ends[ends.length - 1];
    if (!stop || !first || !last) { return; }
    var n = first; while (n.parentElement && !n.contains(last)) { n = n.parentElement; }      // smallest box holding our whole page
    if (!stop.contains(n) || n === stop) { return; }
    n.classList.add("st-keep2");
    for (var a = n.parentElement; a && a !== stop.parentElement; a = a.parentElement) { a.classList.add("st-p2"); }
    document.documentElement.classList.add("st-tidy");
    var css = document.createElement("style");
    css.textContent = "html.st-tidy .st-p2>:not(.st-p2):not(.st-keep2):not(script):not(style){display:none!important}html.st-tidy .tertiary-navigation{display:none!important}";
    document.head.appendChild(css);
  }
  /* station access list (only when ACCESS_DB is set): who may book the linked robots */
  var ACC = { acc: null, me: null, err: false, ready: !ACCESS_DB }, accessJob = null;
  function startAccess() {
    accessJob = !ACCESS_DB ? Promise.resolve() : Promise.all([loadAccess(ACCESS_DB), whoAmIFull()])
      .then(function (r) { ACC.acc = r[0]; ACC.me = viewAs(r[0], r[1]); }).catch(function () { ACC.err = true; })
      .then(function () { ACC.ready = true; });
  }
  function isLinked(robot) { return !!STATION_DBS[robot]; }
  function stationOf(robot) { return STATION_NAMES[robot] || robot; }
  function needsAccess(robot) { return ALL_ROBOTS_NEED_ACCESS || isLinked(robot); }
  function notAllowed(b) { return !!(ACCESS_DB && ACC.acc && needsAccess(b.robot) && !ACC.acc.may({ id: b.uid, name: b.user }, stationOf(b.robot))); }
  function iMayBook(robot) { return !ACCESS_DB || !needsAccess(robot) || (!ACC.err && !!ACC.acc && ACC.acc.may(ACC.me, stationOf(robot))); }
  function manageLink() {      // Leader and supervisors get a way into the access list
    var a = ACC.acc, me = ACC.me;
    return !!(ACCESS_DB && a && me && (a.isLeader(me) || a.rows.some(function (r) { return r.ok && r.role === "Supervisor" && a.isSupervisor(me, r.station); })));
  }
  function askWhom(robot) { var s = ACC.acc ? ACC.acc.supervisors(stationOf(robot)) : []; return s.length ? s.join(" or ") : "the station supervisor"; }
  /* bookings made on the linked station pages (they have no robot field, so the robot name is added here) */
  function fetchLinked() {
    var names = Object.keys(STATION_DBS).filter(function (n) { return STATION_DBS[n]; });
    return Promise.all(names.map(function (n) {
      return fetchPage("d=" + STATION_DBS[n]).then(function (doc) {
        return readBookings(doc).map(function (b) { b.robot = n; b.el = null; b.station = true; return b; });
      }).catch(function () { return []; });     // no access to that station: skip it
    })).then(function (lists) { return [].concat.apply([], lists).filter(function (b) { return b.date && b.to > b.from; }); })
      .then(function (l) { return (accessJob || Promise.resolve()).then(function () { return l.filter(function (b) { return !notAllowed(b); }); }); });
  }
  /* earlier booking (lower record id – ids are shared by all databases) wins */
  function winners(list) {
    return list.filter(function (o) { return !list.some(function (e) { return e.id < o.id && e.robot === o.robot && e.date === o.date && e.from < o.to && o.from < e.to; }); });
  }
  function boardBlock(board, robot, date) {
    var b = board && board[robot];
    if (!b || (b.status !== "Busy" && b.status !== "Occupied")) { return ""; }
    if (b.until && date > b.until) { return ""; }
    return (b.status === "Occupied" ? "out of service" : "assigned to " + (b.person || "someone")) + (b.until ? " until " + nice(b.until) : "");
  }
  /* problems with one booking; others = the other bookings */
  function problems(b, others, board) {
    var p = [];
    if (!b.robot) { p.push("Choose a robot."); }
    if (!b.date) { p.push("Choose a date."); return p; }
    if (isNaN(b.from) || isNaN(b.to)) { p.push("Choose a start and end time."); return p; }
    if (b.to <= b.from) { p.push("The end time must be after the start time."); }
    else if (b.to - b.from > MAX_HOURS) { p.push("A booking can be at most " + MAX_HOURS + " hours."); }
    if (b.from < OPEN || b.to > CLOSE) { p.push("Bookings are possible between " + hh(OPEN) + " and " + hh(CLOSE) + "."); }
    if (DAYS.indexOf(dow(b.date)) < 0) { p.push("The lab is closed on " + nice(b.date) + "."); }
    var bl = boardBlock(board, b.robot, b.date);
    if (bl) { p.push(b.robot + " is " + bl + " (availability board)."); }
    others.forEach(function (o) {
      if (o.robot === b.robot && o.date === b.date && b.from < o.to && o.from < b.to) {
        p.push("Already booked " + hh(o.from) + "–" + hh(o.to) + " by " + (o.user || "someone") + (o.station ? " (station booking)" : "") + ".");
      }
    });
    return p;
  }

  /* ---------------- list page ---------------- */
  function listPage(list) {
    var all = readBookings(document), t = today(), h = new Date().getHours(), board = null, linked = [];
    var state = { tab: "upcoming", robot: "", q: "" };
    try { state.tab = sessionStorage.getItem("bk-tab") || "upcoming"; } catch (e) {}
    var phase = function (b) { return !b.date ? "upcoming" : b.date < t || (b.date === t && b.to <= h) ? "past" : b.date === t && b.from <= h ? "now" : "upcoming"; };

    function draw() {
      Array.prototype.forEach.call(list.querySelectorAll(".bk-js"), function (x) { x.remove(); });
      all.forEach(function (b) {
        b.phase = phase(b);
        b.na = notAllowed(b);
        var earlier = all.concat(linked).filter(function (o) { return o !== b && o.id < b.id && !notAllowed(o); });
        var pr = b.na ? [(b.user || "This person") + " is not on the access list for " + b.robot + " – this booking doesn't count."] : problems(b, earlier, board);
        var flag = b.el.querySelector(".bk-flag"), loc = b.el.querySelector(".bk-loc");
        b.el.className = "bk-e bk-" + b.phase + (pr.length ? " bk-bad" : "");
        flag.innerHTML = b.na ? '<span class="bk-badge bad">Not allowed</span>' : pr.length ? '<span class="bk-badge bad">Problem</span>' : b.phase === "now" ? '<span class="bk-badge now">Now</span>' : b.phase === "past" ? '<span class="bk-badge">Past</span>' : '<span class="bk-badge ok">Confirmed</span>';
        loc.textContent = (ROBOTS[b.robot] || {}).cell || "";
        var pe = b.el.querySelector(".bk-problems");
        if (!pe) { pe = document.createElement("div"); pe.className = "bk-problems"; b.el.insertBefore(pe, b.el.querySelector(".bk-actions")); }
        pe.innerHTML = pr.map(function (x) { return "<div>" + esc(x) + "</div>"; }).join("") + (pr.length ? "<div><b>Please change or delete this booking.</b></div>" : "");
      });
      var show = all.filter(function (b) {
        var okTab = state.tab === "all" || (state.tab === "past" ? b.phase === "past" : state.tab === "today" ? b.date === t : b.phase !== "past");
        var okR = !state.robot || b.robot === state.robot;
        var okQ = !state.q || (b.robot + " " + b.user + " " + b.note).toLowerCase().indexOf(state.q) >= 0;
        return okTab && okR && okQ;
      });
      var asc = state.tab !== "past";
      show.sort(function (a, b) { var k = (a.date + pad(a.from)).localeCompare(b.date + pad(b.from)); return asc ? k : -k; });
      all.forEach(function (b) { b.el.style.display = "none"; });
      var last = "";
      show.forEach(function (b) {
        if (b.date !== last) {
          var hd = document.createElement("h4"); hd.className = "bk-dayhead bk-js";
          hd.textContent = b.date ? (b.date === t ? "Today · " : "") + nice(b.date) : "No date"; list.appendChild(hd); last = b.date;
        }
        b.el.style.display = ""; list.appendChild(b.el);
      });
      if (!show.length) { var e = document.createElement("p"); e.className = "bk-empty bk-js"; e.textContent = state.tab === "upcoming" ? "No upcoming bookings." : "No bookings match these filters."; list.appendChild(e); }
      var up = all.filter(function (b) { return b.phase !== "past"; }).length, now = all.filter(function (b) { return b.phase === "now"; }).length;
      var bad = all.filter(function (b) { return /bk-bad/.test(b.el.className) && b.phase !== "past"; }).length;
      document.getElementById("bk-summary").innerHTML = "<b>" + up + "</b> upcoming · <b>" + now + "</b> running now" + (bad ? ' · <span class="bad">' + bad + " with a problem</span>" : "");
      Array.prototype.forEach.call(document.querySelectorAll(".bk-tabs button"), function (b) { b.setAttribute("aria-pressed", b.getAttribute("data-t") === state.tab); });
    }

    var robots = Object.keys(ROBOTS), sel = document.getElementById("bk-robot");
    sel.innerHTML = '<option value="">All robots</option>' + robots.map(function (r) { return "<option>" + esc(r) + "</option>"; }).join("");
    sel.onchange = function () { state.robot = sel.value; draw(); };
    var qi = document.getElementById("bk-q"); qi.oninput = function () { state.q = qi.value.toLowerCase().trim(); draw(); };
    Array.prototype.forEach.call(document.querySelectorAll(".bk-tabs button"), function (b) {
      b.onclick = function () { state.tab = b.getAttribute("data-t"); try { sessionStorage.setItem("bk-tab", state.tab); } catch (e) {} draw(); };
    });
    var add = document.getElementById("bk-add"); if (add) { add.href = "edit.php?" + selfQuery(); }
    if (document.querySelector(".pagination, .paging")) {
      var hint = document.getElementById("bk-pagehint");
      hint.innerHTML = 'Some bookings are on other pages, so conflicts are only checked on this page. <a href="view.php?' + selfQuery() + '&perpage=1000">Show all bookings on one page</a>.';
      hint.hidden = false;
    }
    draw();
    if (AVAIL_DB) { fetchPage("d=" + AVAIL_DB).then(function (doc) { board = readBoard(doc); draw(); }).catch(function () {}); }
    fetchLinked().then(function (l) { linked = l; if (l.length) { draw(); } });
    if (ACCESS_DB) { accessJob.then(draw); }
    var ov = document.getElementById("bk-overview"); if (ov) { overview(ov); }
  }

  /* ---------------- robot overview (tiles) ---------------- */
  function firstOpenDay() {
    var d = new Date(), h = d.getHours();
    for (var i = 0; i < 14; i++) {
      var s = iso(d.getFullYear(), d.getMonth() + 1, d.getDate());
      if (DAYS.indexOf(dow(s)) >= 0 && !(i === 0 && h >= CLOSE - 1)) { return s; }
      d.setDate(d.getDate() + 1);
    }
    return today();
  }
  function overview(root) {
    var st = { date: firstOpenDay(), from: 9, to: 12, cell: "", q: "", filter: "all" };
    if (st.date === today()) { st.from = Math.min(Math.max(OPEN, new Date().getHours() + 1), CLOSE - 1); }
    st.to = Math.min(st.from + 3, CLOSE);
    var bookings = null, board = null, failed = false;
    var cells = Object.keys(ROBOTS).map(function (n) { return ROBOTS[n].cell; }).filter(function (c, i, a) { return c && a.indexOf(c) === i; }).sort();
    function hours(a, b, v) { var o = ""; for (var x = a; x <= b; x++) { o += '<option value="' + x + '"' + (x === v ? " selected" : "") + ">" + hh(x) + "</option>"; } return o; }
    function blockText(b) {
      return b.status === "Occupied" ? "Out of service" + (b.until ? " until " + nice(b.until) : "") : "Assigned to " + (b.person || "someone") + (b.until ? " until " + nice(b.until) : "");
    }
    function stateOf(name) {
      var s = st.date, bl = board && board[name];
      if (DAYS.indexOf(dow(s)) < 0) { return { k: "blocked", info: "Lab closed on this day" }; }
      if (bl && (bl.status === "Busy" || bl.status === "Occupied") && !(bl.until && s > bl.until)) { return { k: "blocked", info: blockText(bl) }; }
      var day = (bookings || []).filter(function (b) { return b.robot === name && b.date === s; }).sort(function (a, b) { return a.from - b.from; });
      var hit = day.filter(function (b) { return b.from < st.to && st.from < b.to; });
      if (hit.length) { return { k: "booked", info: hit.map(function (b) { return hh(b.from) + "–" + hh(b.to) + " · " + esc(b.user) + (b.station ? " (station)" : ""); }).join("<br>") }; }
      var next = day.filter(function (b) { return b.from >= st.to; })[0];
      return { k: "free", info: "Free " + hh(st.from) + "–" + hh(st.to) + (next ? " · next booking " + hh(next.from) : "") };
    }
    var K = { free: ["ok", "Free"], booked: ["now", "Booked"], blocked: ["bad", "Not bookable"] };
    function draw() {
      var q = st.q.toLowerCase();
      var all = Object.keys(ROBOTS).filter(function (n) {
        var r = ROBOTS[n];
        if (ONLY_MY_ROBOTS && ACCESS_DB && (!ACC.ready || !iMayBook(n))) { return false; }     // only the robots you may book
        return (!st.cell || r.cell === st.cell) && (!q || (n + " " + r.maker + " " + r.cell).toLowerCase().indexOf(q) >= 0);
      }).map(function (n) { return { name: n, r: ROBOTS[n], s: stateOf(n) }; });
      var count = function (k) { return k === "all" ? all.length : all.filter(function (x) { return x.s.k === k; }).length; };
      var shown = all.filter(function (x) { return st.filter === "all" || x.s.k === st.filter; });
      var open = DAYS.indexOf(dow(st.date)) >= 0;
      root.innerHTML =
        '<div class="bk-filters">' +
          '<label>Date<input type="date" id="ovDate" value="' + st.date + '" min="' + today() + '"></label>' +
          '<label>From<select id="ovFrom">' + hours(OPEN, CLOSE - 1, st.from) + '</select></label>' +
          '<label>To<select id="ovTo">' + hours(OPEN + 1, CLOSE, st.to) + '</select></label>' +
          '<label>Location<select id="ovCell"><option value="">All locations</option>' + cells.map(function (c) { return "<option" + (c === st.cell ? " selected" : "") + ">" + esc(c) + "</option>"; }).join("") + '</select></label>' +
          '<label>Search<input type="search" id="ovQ" placeholder="Robot, maker, type" value="' + esc(st.q) + '"></label>' +
        '</div>' +
        (manageLink() ? '<div class="bk-manage"><a class="btn btn-secondary" href="view.php?d=' + ACCESS_DB + '">👥 Manage access</a></div>' : "") +
        '<div class="bk-ovbar"><div class="bk-chips">' + [["all", "All"], ["free", "Free"], ["booked", "Booked"], ["blocked", "Not bookable"]].map(function (c) {
          return '<button type="button" class="bk-chip" data-f="' + c[0] + '" aria-pressed="' + (st.filter === c[0]) + '">' + c[1] + " (" + count(c[0]) + ")</button>"; }).join("") + '</div>' +
          '<div class="bk-legend"><span class="bk-badge ok">● Free</span><span class="bk-badge now">● Booked in this window</span><span class="bk-badge bad">● Not bookable</span></div></div>' +
        '<p class="bk-freeinfo">' + (bookings === null && !failed ? "Loading bookings…" : !open ? "The lab is closed on " + nice(st.date) + " – choose a weekday." :
          "<b>" + count("free") + " of " + all.length + "</b> robots free on " + nice(st.date) + ", " + hh(st.from) + "–" + hh(st.to)) +
          (failed ? ' <span class="bad">(couldn\'t load the bookings – please reload)</span>' : "") + "</p>" +
        '<div class="bk-tiles">' + shown.map(function (x) {
          var k = K[x.s.k], img = IMG[x.r.art];
          var href = "edit.php?" + selfQuery() + "&robot=" + encodeURIComponent(x.name) + "&date=" + st.date + "&from=" + st.from + "&to=" + Math.min(st.to, st.from + MAX_HOURS);
          return '<article class="bk-tile bk-t-' + x.s.k + '">' +
            '<div class="bk-t-head"><div><div class="bk-t-name">' + esc(x.name) + '</div><div class="bk-t-place">' + esc(x.r.cell) + " · " + esc(x.r.maker) + '</div></div><span class="bk-badge ' + k[0] + '">● ' + k[1] + "</span></div>" +
            '<div class="bk-t-img">' + (img ? '<img src="' + img + '" alt="">' : "") + "</div>" +
            '<div class="bk-t-info">' + (x.s.k === "booked" ? x.s.info : esc(x.s.info)) + "</div>" +
            (x.s.k === "free" && bookings !== null ? (iMayBook(x.name) ? '<a class="btn btn-primary bk-t-btn" href="' + href + '">Book</a>'
              : '<div class="bk-t-noaccess">No booking access – ask ' + esc(askWhom(x.name)) + "</div>") : "") +
          "</article>";
        }).join("") + "</div>" + (shown.length ? "" : '<p class="bk-empty">' + (ONLY_MY_ROBOTS && ACCESS_DB && !ACC.ready ? "Loading your robots…" : ONLY_MY_ROBOTS && ACCESS_DB && !st.q && !st.cell && st.filter === "all" ? (ACC.err ? "Couldn't load the access list – please reload the page." : "You don't have access to any robot yet – ask a supervisor.") : "No robot matches these filters.") + "</p>");

      var set = function () {
        st.date = document.getElementById("ovDate").value || st.date;
        st.from = +document.getElementById("ovFrom").value; st.to = +document.getElementById("ovTo").value;
        if (st.to <= st.from) { st.to = Math.min(st.from + 1, CLOSE); }
        st.cell = document.getElementById("ovCell").value; draw();
      };
      ["ovDate", "ovFrom", "ovTo", "ovCell"].forEach(function (id) { document.getElementById(id).onchange = set; });
      var qi = document.getElementById("ovQ");
      qi.oninput = function () { st.q = qi.value; var p = qi.selectionStart; draw(); var x = document.getElementById("ovQ"); x.focus(); x.setSelectionRange(p, p); };
      Array.prototype.forEach.call(root.querySelectorAll(".bk-chip"), function (b) { b.onclick = function () { st.filter = b.getAttribute("data-f"); draw(); }; });
    }
    draw();
    var own = null, linked = [];
    var jobs = [fetchPage(selfQuery()).then(function (doc) {
      own = readBookings(doc).filter(function (b) { return b.date && b.to > b.from; });
    }), fetchLinked().then(function (l) { linked = l; })];
    if (AVAIL_DB) { jobs.push(fetchPage("d=" + AVAIL_DB).then(function (doc) { board = readBoard(doc); }).catch(function () {})); }
    jobs.push(accessJob);
    Promise.all(jobs).then(function () { bookings = winners(own.filter(function (b) { return !notAllowed(b); }).concat(linked)); draw(); }).catch(function () { failed = true; bookings = []; draw(); });
  }

  /* ---------------- add / edit page ---------------- */
  function formPage(form) {
    var robotSel = form.querySelector(".bkf-robot select"), fromSel = form.querySelector(".bkf-from select"), toSel = form.querySelector(".bkf-to select");
    var dsel = function (part) { return form.querySelector('.bkf-date select[name$="_' + part + '"]'); };
    var box = document.getElementById("bk-check"), others = null, board = null, linked = [], rid = +param("rid") || 0;
    var pre = param("robot"), pd = param("date").match(/^(\d{4})-(\d{2})-(\d{2})$/), pf = +param("from"), pt = +param("to");
    var setSel = function (sel, fn) { if (sel) { Array.prototype.forEach.call(sel.options, function (o) { if (fn(o)) { sel.value = o.value; } }); } };
    if (pd && !rid) { setSel(dsel("year"), function (o) { return +o.value === +pd[1]; }); setSel(dsel("month"), function (o) { return +o.value === +pd[2]; }); setSel(dsel("day"), function (o) { return +o.value === +pd[3]; }); }
    if (pf && !rid) { setSel(fromSel, function (o) { return hour(o.text) === pf; }); }
    if (pt && !rid) { setSel(toSel, function (o) { return hour(o.text) === pt; }); }
    if (pre && robotSel && !robotSel.value) { Array.prototype.forEach.call(robotSel.options, function (o) { if (o.value === pre || o.text === pre) { robotSel.value = o.value; } }); }

    function current() {
      var y = dsel("year"), m = dsel("month"), d = dsel("day");
      return { robot: robotSel ? robotSel.value : "", date: y && m && d ? iso(+y.value, +m.value, +d.value) : "",
        from: hour(fromSel ? fromSel.options[fromSel.selectedIndex].text : ""), to: hour(toSel ? toSel.options[toSel.selectedIndex].text : "") };
    }
    function check(final) {
      var b = current(), p = problems(b, others || [], board), nowH = new Date().getHours();
      if (b.robot && ACCESS_DB && ACC.ready && !iMayBook(b.robot)) { p.unshift(ACC.err ? "Couldn't load the station access list – please reload the page." : b.robot + " is also a station: you need to be on its access list. Ask " + askWhom(b.robot) + " to add you."); }
      if (b.date && (b.date < today() || (b.date === today() && b.from < nowH))) { p.unshift("That time has already passed."); }
      var day = others && b.robot && b.date ? others.filter(function (o) { return o.robot === b.robot && o.date === b.date; }).sort(function (a, c) { return a.from - c.from; }) : [];
      var dayTxt = day.length ? "<div class='bk-dayline'>Other bookings for this robot on " + nice(b.date) + ": " + day.map(function (o) { return hh(o.from) + "–" + hh(o.to) + " (" + esc(o.user) + ")"; }).join(", ") + "</div>" : "";
      if (others === null || !ACC.ready) { box.className = "bk-checkbox wait"; box.innerHTML = "Checking existing bookings…"; return p; }
      if (p.length) { box.className = "bk-checkbox bad"; box.innerHTML = "<b>" + (final ? "Not saved: " : "") + "please fix this first</b>" + p.map(function (x) { return "<div>" + esc(x) + "</div>"; }).join("") + dayTxt; }
      else if (b.robot && b.date && !isNaN(b.from)) { box.className = "bk-checkbox ok"; box.innerHTML = "<b>✓ " + esc(b.robot) + " is free on " + nice(b.date) + ", " + hh(b.from) + "–" + hh(b.to) + ".</b>" + dayTxt; }
      else { box.className = "bk-checkbox"; box.innerHTML = "Choose a robot, date and time."; }
      return p;
    }
    [robotSel, fromSel, toSel, dsel("day"), dsel("month"), dsel("year")].forEach(function (s) {
      if (s) { s.addEventListener("change", function () {
        var toH = toSel ? hour(toSel.options[toSel.selectedIndex].text) : NaN;
        if (s === fromSel && toSel && (isNaN(toH) || toH <= hour(fromSel.options[fromSel.selectedIndex].text))) {
          var want = hour(fromSel.options[fromSel.selectedIndex].text) + 1;
          Array.prototype.forEach.call(toSel.options, function (o) { if (hour(o.text) === want) { toSel.value = o.value; } });
        }
        check(false);
      }); }
    });
    var f = form.closest("form");
    if (f) { f.addEventListener("submit", function (ev) {
      var sub = ev.submitter && /cancel/i.test(ev.submitter.name || ""); if (sub) { return; }
      if (ACCESS_DB && !ACC.ready) { ev.preventDefault(); return; }
      if (others === null) { return; }
      if (check(true).length) { ev.preventDefault(); box.scrollIntoView({ behavior: "smooth", block: "center" }); }
    }); }
    check(false);
    var jobs = [fetchPage(selfQuery()).then(function (doc) {
      var all = readBookings(doc);
      // a booking that clashes with an earlier one is already marked "Problem" – it doesn't block others
      others = all.filter(function (o) {
        return o.id !== rid && !all.some(function (e) { return e.id < o.id && e.robot === o.robot && e.date === o.date && e.from < o.to && o.from < e.to; });
      });
    }), fetchLinked().then(function (l) { linked = l; })];
    if (AVAIL_DB) { jobs.push(fetchPage("d=" + AVAIL_DB).then(function (doc) { board = readBoard(doc); }).catch(function () {})); }
    jobs.push(accessJob);
    Promise.all(jobs).then(function () { others = winners(others.concat(linked.filter(function (o) { return o.id !== rid; })).filter(function (o) { return !notAllowed(o); })); check(false); }).catch(function () {
      others = []; check(false);
      box.insertAdjacentHTML("beforeend", "<div class='bk-dayline'>Couldn't load the other bookings – conflicts will be flagged on the list page.</div>");
    });
  }

  function run() {
    startAccess();
    var list = document.querySelector(".bk-list"); if (list) { acTidy(); listPage(list); }
    var form = document.querySelector(".bk-form"); if (form) { formPage(form); }
  }
  if (document.readyState === "loading") { document.addEventListener("DOMContentLoaded", run); } else { run(); }
  /* robot pictures (kept at the end so the settings stay short) */
  function pictures() { return {"wavego_bionic": "data:image/webp;base64,", "galaxy_rvr_rover": "data:image/webp;base64,", "rasprover_tracked": "data:image/webp;base64,", "berrybase_chassis": "data:image/webp;base64,", "mecanum": "data:image/webp;base64,", "so_arm": "data:image/webp;base64,", "stackforce_wheeled": "data:image/webp;base64,", "playtastic_humanoid": "data:image/webp;base64,", "turtlebot3": "data:image/webp;base64,", "hexapod": "data:image/webp;base64,", "taurob": "data:image/webp;base64,", "zelos": "data:image/webp;base64,", "mir_ur5": "data:image/webp;base64,", "humanoid": "data:image/webp;base64,", "robotino": "data:image/webp;base64,", "kuka_kr16": "data:image/webp;base64,", "wittmann": "data:image/webp;base64,", "ur5": "data:image/webp;base64,", "abb_gofa": "data:image/webp;base64,", "kuka_kr6": "data:image/webp;base64,", "fanuc_m6ib": "data:image/webp;base64,", "fanuc_er4ia": "data:image/webp;base64,"}; }
})();